<script setup>
/**
 * SkeletonLoader.vue - 骨架屏加载组件
 * 
 * 支持类型:
 * - card: 卡片骨架 (图片 + 标题 + 描述行)
 * - list: 列表骨架 (头像 + 标题 + 多行描述)
 * - text: 纯文本骨架 (多行)
 * - avatar: 头像+信息骨架
 * 
 * Props:
 * - type: 'card' | 'list' | 'text' | 'avatar' - 骨架类型 (默认: card)
 * - count: number - 重复数量 (默认: 1)
 */

defineProps({
  type: {
    type: String,
    default: 'card',
    validator(value) {
      return ['card', 'list', 'text', 'avatar'].includes(value)
    }
  },
  count: {
    type: Number,
    default: 1
  }
})
</script>

<template>
  <div class="skeleton-loader">
    <template v-for="n in count" :key="n">
      <!-- 卡片骨架 -->
      <div v-if="type === 'card'" class="skeleton-card">
        <div class="skeleton-image shimmer"></div>
        <div class="skeleton-card-body">
          <div class="skeleton-title shimmer"></div>
          <div class="skeleton-line shimmer" style="width: 70%"></div>
          <div class="skeleton-line shimmer" style="width: 50%"></div>
        </div>
      </div>

      <!-- 列表骨架 -->
      <div v-else-if="type === 'list'" class="skeleton-list-item">
        <div class="skeleton-avatar shimmer"></div>
        <div class="skeleton-list-body">
          <div class="skeleton-title shimmer" style="width: 40%"></div>
          <div class="skeleton-line shimmer" style="width: 90%"></div>
          <div class="skeleton-line shimmer" style="width: 60%"></div>
        </div>
      </div>

      <!-- 纯文本骨架 -->
      <div v-else-if="type === 'text'" class="skeleton-text">
        <div class="skeleton-line shimmer" style="width: 100%"></div>
        <div class="skeleton-line shimmer" style="width: 95%"></div>
        <div class="skeleton-line shimmer" style="width: 85%"></div>
        <div class="skeleton-line shimmer" style="width: 70%"></div>
      </div>

      <!-- 头像+信息骨架 -->
      <div v-else-if="type === 'avatar'" class="skeleton-avatar-card">
        <div class="skeleton-avatar-large shimmer"></div>
        <div class="skeleton-avatar-info">
          <div class="skeleton-title shimmer" style="width: 50%"></div>
          <div class="skeleton-line shimmer" style="width: 80%"></div>
          <div class="skeleton-line shimmer" style="width: 40%"></div>
        </div>
      </div>
    </template>
  </div>
</template>

